function tapUp(onData, onError, onCompletion) {
  return function (source) {
    return function (start, sink) {
      if (start !== 0) return;
      var talkback;
      source(0, function (type, data) {
        if (type !== 0) {
          sink(type, data);
          return;
        }

        talkback = data;
        sink(0, function (type, data) {
          if (type === 1) {
            onData(data);
          } else if (type === 2) {
            if (data) {
              if (onError) {
                onError(data);
              }
            } else if (onCompletion) {
              onCompletion();
            }
          }

          talkback(type, data);
        });
      });
    };
  };
}

export default tapUp;
